// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(bytes calldata data) public {
        Reverter r = new Reverter();
        bool ok = true;
        try c.forward(address(r), data) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: forwarding to a callee that reverts must revert forward too.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

