pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        SelfDestructing helper = new SelfDestructing();
        vm.deal(address(helper), amount);
        uint256 before = address(c).balance;
        c.forward(address(helper), "");
        assertTrue(address(c).balance == before + amount);
    }
}

contract SelfDestructing {
    fallback() external payable {
        selfdestruct(payable(msg.sender));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, bytes memory data) public {
        vm.assume(actor != address(0));
        vm.assume(data.length > 0);
        Recorder target = new Recorder();
        bool ok;
        vm.prank(actor);
        try c.forward(address(target), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Recorder {
    fallback(bytes calldata _data) external returns (bytes memory) {
        require(_data.length > 0, "empty calldata");
        return hex"";
    }
}

contract InvMutTest {
    C c;
    uint hits;

    constructor(C _c) { c = _c; }

    fallback() external { hits++; }

    function t(address callee, bytes memory data) public {
        require(callee == address(this));
        c.forward(callee, data);
        assert(hits == 1);
    }
}

